using System;using System.Collections.Generic;using UnityEngine;
namespace FashionFit {
 public sealed class GarmentLayerPart:MonoBehaviour {public LayeredAoDai Owner;public int Layer;public bool Interactable=>Owner&&(Owner.SelectedLayer<0||Owner.SelectedLayer==Layer);}
 // Low-resolution open panel with independent free hem and side edges.
 public sealed class LayeredPanel:MonoBehaviour {
  struct Edge{public int a,b;public float length,warp,area;public bool bend;}
  public Vector3[] Positions{get;private set;}public Vector3[] Previous{get;private set;}public Vector3[] Rest{get;private set;}public int[] Faces{get;private set;}
  public string Label{get;private set;}public MembraneReading Reading{get;private set;}public MembraneMaterial Material=MembraneMaterial.Presets[0];public Mesh Mesh{get;private set;}
  public int GrabCount=>(grab[0]>=0?1:0)+(grab[1]>=0?1:0);public float MaxRatio{get;private set;}
  readonly Dictionary<int,Vector3> arrangementPins=new Dictionary<int,Vector3>();NativePanelStep native;readonly int[] grab={-1,-1};readonly Vector3[] targets=new Vector3[2];List<Edge> edges=new List<Edge>();float[] lambda;Vector3[] anchors,recovery;int columns;LayeredAoDai owner;Matrix4x4 oldHip;bool recovering;float recoveryAge;
  public void Initialize(LayeredAoDai a,string label,Vector3[] points,Vector2[] uv,int[] triangles,int cols,Material material){owner=a;Label=label;Rest=(Vector3[])points.Clone();Positions=(Vector3[])points.Clone();Previous=(Vector3[])points.Clone();anchors=(Vector3[])points.Clone();columns=cols;Faces=triangles;oldHip=a.HipMatrix;var unique=new HashSet<long>();Action<int,int,bool> add=(i,j,bend)=>{long key=((long)Mathf.Min(i,j)<<32)|(uint)Mathf.Max(i,j);if(!unique.Add(key))return;Vector3 d=points[j]-points[i];float len=d.magnitude;if(len>.001f)edges.Add(new Edge{a=i,b=j,length=len,warp=d.y*d.y/d.sqrMagnitude,area=.0009f,bend=bend});};for(int f=0;f<triangles.Length;f+=3){add(triangles[f],triangles[f+1],false);add(triangles[f+1],triangles[f+2],false);add(triangles[f+2],triangles[f],false);}int rows=points.Length/cols;for(int r=0;r<rows;r++)for(int c=0;c<cols;c++){int i=r*cols+c;if(r+2<rows)add(i,i+2*cols,true);if(c+2<cols)add(i,i+2,true);}lambda=new float[edges.Count];var links=new NativePanelStep.Edge[edges.Count];for(int i=0;i<links.Length;i++){var e=edges[i];links[i]=new NativePanelStep.Edge{a=e.a,b=e.b,length=e.length,warp=e.warp,area=e.area,bend=e.bend};}native=new NativePanelStep(points,triangles,links,a.RoomBounds);Mesh=new Mesh{name=label+" open simulation panel"};Mesh.MarkDynamic();Mesh.vertices=Positions;Mesh.uv=uv;Mesh.triangles=Faces;gameObject.AddComponent<MeshFilter>().sharedMesh=Mesh;gameObject.AddComponent<MeshRenderer>().sharedMaterial=material;var box=gameObject.AddComponent<BoxCollider>();box.isTrigger=true;gameObject.layer=9;gameObject.AddComponent<RunwayVRGrabTarget>().ConfigurePanel(this);Publish();}
  public bool Nearest(Vector3 world,float reach,out Vector3 point)=>GarmentPicking.Mesh(Positions,Faces,transform.localToWorldMatrix,world,reach,out point,out _);
  readonly Vector3[] gripOrigin=new Vector3[2];public float GripTravelM=>Mathf.Max(grab[0]>=0?Vector3.Distance(targets[0],gripOrigin[0]):0,grab[1]>=0?Vector3.Distance(targets[1],gripOrigin[1]):0);
  public bool BeginGrip(int slot,Vector3 world){if(slot<0||slot>1||grab[slot]>=0||!GetComponent<GarmentLayerPart>().Interactable)return false;if(!GarmentPicking.Mesh(Positions,Faces,transform.localToWorldMatrix,world,.12f,out _,out int index)||index<columns||index==grab[1-slot])return false;if(GrabCount==0)recovery=(Vector3[])Positions.Clone();arrangementPins.Remove(index);owner.Wake();grab[slot]=index;targets[slot]=Positions[index];gripOrigin[slot]=Positions[index];recovering=false;return true;}
  public void MoveGrip(int slot,Vector3 world){if(slot>=0&&slot<2&&grab[slot]>=0&&RunwayVRHands.ValidPose(world,Quaternion.identity))targets[slot]=transform.InverseTransformPoint(world);}
  public void EndGrip(int slot,bool cancelled=false){if(slot<0||slot>1)return;if(owner.ArrangementMode&&!cancelled&&grab[slot]>=0)arrangementPins[grab[slot]]=Positions[grab[slot]];grab[slot]=-1;owner.Wake();if(GrabCount==0&&recovery!=null){recovering=true;recoveryAge=0;}}
  bool Held(int i)=>i==grab[0]||i==grab[1];
  public void ResetShape(){grab[0]=grab[1]=-1;recovering=false;arrangementPins.Clear();var hip=owner.HipMatrix;for(int i=0;i<Rest.Length;i++)Positions[i]=Previous[i]=hip.MultiplyPoint3x4(Rest[i]);oldHip=hip;Publish();}
  public void Step(float dt){dt=Mathf.Clamp(dt,.001f,1f/30);var hip=owner.HipMatrix;Matrix4x4 transport=hip*oldHip.inverse;for(int i=0;i<Positions.Length;i++){Positions[i]=transport.MultiplyPoint3x4(Positions[i]);Previous[i]=transport.MultiplyPoint3x4(Previous[i]);anchors[i]=hip.MultiplyPoint3x4(Rest[i]);if(recovery!=null)recovery[i]=transport.MultiplyPoint3x4(recovery[i]);}oldHip=hip;
   Vector3 gravity=owner.LocalGravity;float damping=Mathf.Exp(-3.2f*dt);for(int i=0;i<Positions.Length;i++){Vector3 p=Positions[i],velocity=Vector3.ClampMagnitude((p-Previous[i])*damping,.045f);Previous[i]=p;Positions[i]=i<columns?anchors[i]:p+velocity+gravity*(dt*dt);}
   if(recovering){float blend=1-Mathf.Exp(-dt/Material.recoverySeconds);for(int i=columns;i<Positions.Length;i++)Positions[i]=Vector3.Lerp(Positions[i],recovery[i],blend);recoveryAge+=dt;if(recoveryAge>Material.recoverySeconds*5)recovering=false;}
   Vector3[] accepted=new Vector3[2];for(int s=0;s<2;s++)if(grab[s]>=0){int id=grab[s];Vector3 goal=Vector3.MoveTowards(Positions[id],targets[s],.022f);int top=id%columns;float path=Mathf.Abs(Rest[id].y-Rest[top].y)+.04f;goal=anchors[top]+Vector3.ClampMagnitude(goal-anchors[top],path*(1+Mathf.Min(.25f,Material.maxStrain)));accepted[s]=owner.Contact(goal,Previous[id],this);}
   native.Run(owner,Positions,Previous,anchors,columns,Material,dt,grab[0],grab[1],accepted[0],accepted[1],false,this==owner.Front);
   if(owner.ArrangementMode){foreach(var pin in arrangementPins)Positions[pin.Key]=owner.Contact(pin.Value,pin.Value,this);}else arrangementPins.Clear();
   Reading=new MembraneReading{hasStiffness=true};var reading=Reading;MaxRatio=1;foreach(var e in edges)if(!e.bend){float strain=(Vector3.Distance(Positions[e.a],Positions[e.b])-e.length)/e.length,force=Mathf.Lerp(Material.SheetWeft,Material.SheetWarp,e.warp)*strain*(strain<0?Material.compressionRatio:1);reading.tensileStrain=Mathf.Max(reading.tensileStrain,strain);reading.compressiveStrain=Mathf.Max(reading.compressiveStrain,-strain);reading.tensionNm=Mathf.Max(reading.tensionNm,force);reading.compressionNm=Mathf.Max(reading.compressionNm,-force);MaxRatio=Mathf.Max(MaxRatio,1+strain);}Reading=reading;
  }
  public void ResolveContacts(){native.Run(owner,Positions,Previous,anchors,columns,Material,1f/60,grab[0],grab[1],Vector3.zero,Vector3.zero,true,this==owner.Front);}
  void ProjectAll(){for(int i=0;i<Positions.Length;i++)Positions[i]=owner.Contact(Positions[i],Previous[i],this);for(int pass=0;pass<2;pass++)for(int f=0;f<Faces.Length;f+=3){int a=Faces[f],b=Faces[f+1],c=Faces[f+2];Vector3 p=(Positions[a]+Positions[b]+Positions[c])/3,previous=(Previous[a]+Previous[b]+Previous[c])/3,d=owner.Contact(p,previous,this)-p;Positions[a]+=d;Positions[b]+=d;Positions[c]+=d;}for(int i=0;i<Positions.Length;i++)Positions[i]=owner.Contact(Positions[i],Previous[i],this);}
  public void Publish(){Mesh.vertices=Positions;Mesh.RecalculateNormals();Mesh.RecalculateBounds();Mesh.RecalculateTangents();var box=GetComponent<BoxCollider>();box.center=Mesh.bounds.center;box.size=Mesh.bounds.size+Vector3.one*.04f;}
  void OnDestroy(){if(native!=null)native.Dispose();if(Mesh){if(Application.isPlaying)Destroy(Mesh);else DestroyImmediate(Mesh);}}
 }
}
